export const john9Sv: Chapter = {
  ...john9,
  title: "Den blindfödde",
  summary: "Jesus botar en man som varit **blind från födseln** — inte för att någon syndat, utan *för att Guds gärningar skulle uppenbaras* — smörjer hans ögon med lera och sänder honom att tvätta sig vid **Siloa** (som betyder *Sänd*). Botandet på en sabbat utlöser ett allt hårdare förhör. Mannens svar blir djärvare medan myndigheternas blir hårdare: *”Ett vet jag — jag var blind, nu ser jag.”* Hotade med att bli **utstötta ur synagogan** viker hans föräldrar undan; mannen argumenterar sina förhörare i botten och blir **utkastad**. Jesus finner honom, och för den utstötte ensam uppenbarar han sig — *”Herre, jag tror,”* och han tillber. Kapitlet slutar i sin stora omkastning: de seende är blinda, den blinde ser; *”till en dom har jag kommit till denna värld.”*",
  verses: john9.verses.map((v) => ({
    ...v,
    english: OVERLAY[v.verse]?.english ?? v.english,
    annotations: OVERLAY[v.verse]?.annotations ?? v.annotations,
  })),
};
